def test_dataframe_columns(run, x):
    import pandas as pd
    try:
        answer = run(x)
    except Exception:
        assert False
    assert isinstance(answer, pd.DataFrame)
    assert list(answer.columns) == ['Product', 'Sales', 'Profit']

def test_empty_product_report(run, x):
    try:
        answer = run(x)
    except Exception:
        assert False
    if not x['products']:
        assert answer.empty

def test_grouped_products(run, x):
    try:
        answer = run(x)
    except Exception:
        assert False
    assert answer['Product'].is_unique
    assert set(answer['Product']).issubset(set(x['products']))

def test_sales_range_aggregate(run, x):
    try:
        answer = run(x)
    except Exception:
        assert False
    assert all(float(v).is_integer() and v >= 0 for v in answer['Sales'])
    assert all(v <= x['n_samples'] * x['sales_upper'] for v in answer['Sales'])

def test_profit_margin_bounds(run, x):
    try:
        answer = run(x)
    except Exception:
        assert False
    if x['profit_margin_min'] <= x['profit_margin_max']:
        for sales, profit in zip(answer['Sales'], answer['Profit']):
            assert sales * x['profit_margin_min'] - 1e-9 <= profit <= sales * x['profit_margin_max'] + 1e-9

def test_sorted_by_profit(run, x):
    try:
        answer = run(x)
    except Exception:
        assert False
    profits = list(answer['Profit'])
    assert all(profits[i] >= profits[i + 1] for i in range(len(profits) - 1))

def test_seeded_sales_oracle(run, x):
    import numpy as np
    try:
        answer = run(x)
    except Exception:
        assert False
    if not x['products']:
        assert answer.empty
        return
    rng = np.random.RandomState(x['random_seed'])
    totals = {}
    for _ in range(x['n_samples']):
        p = rng.choice(x['products'])
        s = rng.randint(x['sales_lower'], x['sales_upper'] + 1)
        rng.uniform(x['profit_margin_min'], x['profit_margin_max'])
        totals[p] = totals.get(p, 0) + s
    assert dict(zip(answer['Product'], answer['Sales'])) == totals

def test_seeded_profit_oracle(run, x):
    import numpy as np
    try:
        answer = run(x)
    except Exception:
        assert False
    if not x['products']:
        assert answer.empty
        return
    rng = np.random.RandomState(x['random_seed'])
    totals = {}
    for _ in range(x['n_samples']):
        p = rng.choice(x['products'])
        s = rng.randint(x['sales_lower'], x['sales_upper'] + 1)
        totals[p] = totals.get(p, 0.0) + s * rng.uniform(x['profit_margin_min'], x['profit_margin_max'])
    got = dict(zip(answer['Product'], answer['Profit']))
    assert set(got) == set(totals)
    assert all(abs(got[p] - totals[p]) < 1e-8 for p in totals)

def test_equal_sales_bounds_allowed(run, x):
    try:
        answer = run(x)
    except Exception:
        assert False
    if x['sales_lower'] == x['sales_upper']:
        assert len(answer) == 1
        assert answer.iloc[0]['Sales'] == x['n_samples'] * x['sales_lower']

def test_equal_margin_bounds_allowed(run, x):
    try:
        answer = run(x)
    except Exception:
        assert False
    if x['profit_margin_min'] == x['profit_margin_max']:
        assert all(abs(p - s * x['profit_margin_min']) < 1e-10 for s, p in zip(answer['Sales'], answer['Profit']))

