def test_direct_enumeration(run, x):
    answer = run(x)
    numbers = x['numbers']
    expected = 0.0
    for size in range(1, len(numbers) + 1):
        for combo in itertools.combinations(numbers, size):
            product = 1
            for value in combo:
                product *= value
            expected += math.log(product)
    assert isinstance(answer, float) and math.isclose(answer, expected, rel_tol=1e-12, abs_tol=1e-12)

def test_coefficient_identity(run, x):
    answer = run(x)
    numbers = x['numbers']
    expected = 0.0 if not numbers else (2 ** (len(numbers) - 1)) * sum(math.log(v) for v in numbers)
    assert isinstance(answer, float) and math.isclose(answer, expected, rel_tol=1e-12, abs_tol=1e-12)

def test_empty_sum(run, x):
    answer = run(x)
    if not x['numbers']:
        assert answer == 0.0
    else:
        assert isinstance(answer, float)

def test_singleton(run, x):
    answer = run(x)
    numbers = x['numbers']
    if len(numbers) == 1:
        assert isinstance(answer, float) and math.isclose(answer, math.log(numbers[0]), rel_tol=1e-12, abs_tol=1e-12)
    else:
        assert isinstance(answer, float)

def test_pair_expansion(run, x):
    answer = run(x)
    numbers = x['numbers']
    if len(numbers) == 2:
        expected = 2.0 * (math.log(numbers[0]) + math.log(numbers[1]))
        assert isinstance(answer, float) and math.isclose(answer, expected, rel_tol=1e-12, abs_tol=1e-12)
    else:
        assert isinstance(answer, float)

def test_uniform_inputs(run, x):
