    if numbers and all(v == numbers[0] for v in numbers):
        expected = (2 ** (len(numbers) - 1)) * len(numbers) * math.log(numbers[0])
        assert isinstance(answer, float) and math.isclose(answer, expected, rel_tol=1e-12, abs_tol=1e-12)
    else:
        assert isinstance(answer, float)

def test_at_least_singletons(run, x):
    answer = run(x)
    lower_bound = sum(math.log(v) for v in x['numbers'])
    assert isinstance(answer, float) and answer >= lower_bound - 1e-12

def test_combo_products(run, x):
    import itertools
    import math
    numbers = x['numbers']
    expected = sum(
        math.log(math.prod(combo))
        for r in range(1, len(numbers) + 1)
        for combo in itertools.combinations(numbers, r)
    )
    answer = run(x)
    assert math.isclose(answer, expected, rel_tol=1e-12, abs_tol=1e-12)

def test_mask_products(run, x):
    import math
    numbers = x['numbers']
    expected = 0.0
    for mask in range(1, 1 << len(numbers)):
        product = 1
        for i, value in enumerate(numbers):
            if mask & (1 << i):
                product *= value
        expected += math.log(product)
    answer = run(x)
    assert math.isclose(answer, expected, rel_tol=1e-12, abs_tol=1e-12)

def test_element_frequency(run, x):
