def test_index_masks(run, x):
    import math
    values = x['numbers']
    expected = 0.0
    for chosen in range(1, 1 << len(values)):
        selected = [values[index] for index in range(len(values)) if chosen >> index & 1]
        expected += math.log(math.prod(selected))
    answer = run(x)
    assert math.isclose(answer, expected, rel_tol=1e-12, abs_tol=1e-12)

def test_recursive_enumeration(run, x):
    import math
    values = x['numbers']
    products = []
    def visit(index, product, used):
        if index == len(values):
            if used:
                products.append(product)
            return
        visit(index + 1, product, used)
        visit(index + 1, product * values[index], True)
    visit(0, 1, False)
    expected = sum(math.log(product) for product in products)
    answer = run(x)
    assert math.isclose(answer, expected, rel_tol=1e-12, abs_tol=1e-12)

def test_float_exhaustive(run, x):
    import itertools
    import math
    values = x['numbers']
    expected = sum(
        math.log(math.prod(choice))
        for count in range(1, len(values) + 1)
        for choice in itertools.combinations(values, count)
    )
    answer = run(x)
    assert isinstance(answer, float) and math.isclose(answer, expected, rel_tol=1e-12, abs_tol=1e-12)

def test_finite_definition_sum(run, x):
    import itertools
    import math
    values = x['numbers']
    terms = []
    for count in range(1, len(values) + 1):
        for choice in itertools.combinations(values, count):
            product = 1
            for value in choice:
                product *= value
            terms.append(math.log(product))
    expected = math.fsum(terms)
    answer = run(x)
    assert math.isfinite(answer) and math.isclose(answer, expected, rel_tol=1e-12, abs_tol=1e-12)
